import{_ as l,a0 as d,w as s,s as a,I as r,x as e,a1 as n,A as i,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Windows 操作系统中运行 Docker 客户端 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Windows 操作系统中运行 Docker 客户端 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Windows 操作系统中运行 Docker 客户端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Windows 操作系统中运行 Docker 客户端 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150512 How To Run Docker Client Inside Windows OS","title":"如何在 Windows 操作系统中运行 Docker 客户端","tag":"201506","desc":""},"relativePath":"201506/20150512 How To Run Docker Client Inside Windows OS.md","filePath":"[post].md"}'),k={name:"201506/20150512 How To Run Docker Client Inside Windows OS.md"};function c(u,o,w,D,h,g){const t=d("Link");return s(),a("div",null,[o[23]||(o[23]=r("h1",{id:"如何在-windows-操作系统中运行-docker-客户端",tabindex:"-1"},[e("如何在 Windows 操作系统中运行 Docker 客户端 "),r("a",{class:"header-anchor",href:"#如何在-windows-操作系统中运行-docker-客户端","aria-label":"Permalink to “如何在 Windows 操作系统中运行 Docker 客户端”"},"​")],-1)),r("p",null,[o[2]||(o[2]=e("大家好，今天我们来了解一下 Windows 操作系统中的 Docker 以及在其中安装 Docker Windows 客户端的知识。Docker 引擎使用 Linux 特有的内核特性，因此不能通过 Windows 内核运行，所以，（在 Windows 上）Docker 引擎创建了一个小的虚拟系统运行 Linux 并利用它的资源和内核。这样，Windows Docker 客户端就可以用这个虚拟的 Docker 引擎来构建、运行以及管理 Docker 容器。有个叫 Boot2Docker 的团队开发了一个同名的应用程序，它创建了一个虚拟机来运行基于",-1)),n(t,{href:"http://tinycorelinux.net/"},{default:i(()=>[...o[0]||(o[0]=[e("Tiny Core Linux",-1)])]),_:1}),o[3]||(o[3]=e("特制的小型 Linux，来在 Windows 上运行 ",-1)),n(t,{href:"https://www.docker.io/"},{default:i(()=>[...o[1]||(o[1]=[e("Docker",-1)])]),_:1}),o[4]||(o[4]=e(" 容器。它完全运行在内存中，需要大约 27M 内存并能在 5秒 (因人而异) 内启动。因此，在用于 Windows 的 Docker 引擎被开发出来之前，我们在 Windows 机器里只能运行 Linux 容器。",-1))]),o[24]||(o[24]=r("p",null,"下面是安装 Docker 客户端并在上面运行容器的简单步骤。",-1)),o[25]||(o[25]=r("h3",{id:"_1-下载-boot2docker",tabindex:"-1"},[e("1. 下载 Boot2Docker "),r("a",{class:"header-anchor",href:"#_1-下载-boot2docker","aria-label":"Permalink to “1. 下载 Boot2Docker”"},"​")],-1)),r("p",null,[o[7]||(o[7]=e("在我们开始安装之前，我们需要 Boot2Docker 的可执行文件。可以从 ",-1)),n(t,{href:"https://github.com/boot2docker/windows-installer/releases/latest"},{default:i(()=>[...o[5]||(o[5]=[e("它的 Github",-1)])]),_:1}),o[8]||(o[8]=e(" 下载最新版本的 Boot2Docker。在这篇指南中，我们从网站中下载版本 v1.6.1。我们从那网页中用我们喜欢的浏览器或者下载管理器下载了名为 ",-1)),n(t,{href:"https://github.com/boot2docker/windows-installer/releases/download/v1.6.1/docker-install.exe"},{default:i(()=>[...o[6]||(o[6]=[e("docker-install.exe",-1)])]),_:1}),o[9]||(o[9]=e(" 的文件。",-1))]),o[26]||(o[26]=p(`<p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/downloading-boot2docker-installer.png" alt=""></p><h3 id="_2-安装-boot2docker" tabindex="-1">2. 安装 Boot2Docker <a class="header-anchor" href="#_2-安装-boot2docker" aria-label="Permalink to “2. 安装 Boot2Docker”">​</a></h3><p>现在我们运行安装文件，它会安装 Window Docker 客户端、用于 Windows 的 Git(MSYS-git)、VirtualBox、Boot2Docker Linux ISO 以及 Boot2Docker 管理工具，这些对于开箱即用地运行全功能的 Docker 引擎都至关重要。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/boot2docker-installer.png" alt=""></p><h3 id="_3-运行-boot2docker" tabindex="-1">3. 运行 Boot2Docker <a class="header-anchor" href="#_3-运行-boot2docker" aria-label="Permalink to “3. 运行 Boot2Docker”">​</a></h3><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/boot2docker-start-icon-e1431322598697.png" alt=""></p><p>安装完成必要的组件之后，我们从桌面上的“Boot2Docker Start”快捷方式启动 Boot2Docker。它会要求你输入以后用于验证的 SSH 密钥。然后会启动一个配置好的用于管理在虚拟机中运行的 Docker 的 unix shell。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/starting-boot2docker.png" alt=""></p><p>为了检查是否正确配置，运行下面的 docker version 命令。</p><pre><code>docker version
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-version.png" alt=""></p><h3 id="_4-运行-docker" tabindex="-1">4. 运行 Docker <a class="header-anchor" href="#_4-运行-docker" aria-label="Permalink to “4. 运行 Docker”">​</a></h3><p>由于 <strong>Boot2Docker Start</strong> 自动启动了一个已经正确设置好环境变量的 shell，我们可以马上开始使用 Docker。<strong>请注意，如果我们要将 Boot2Docker 作为一个远程 Docker 守护进程，那么不要在 docker 命令之前加 sudo。</strong></p><p>现在，让我们来试试 <strong>hello-world</strong> 例子镜像，它会下载 hello-world 镜像，运行并输出 &quot;Hello from Docker&quot; 信息。</p><pre><code>$ docker run hello-world
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/running-hello-world.png" alt=""></p><h3 id="_5-使用命令提示符-cmd-运行-docker" tabindex="-1">5. 使用命令提示符(CMD) 运行 Docker### <a class="header-anchor" href="#_5-使用命令提示符-cmd-运行-docker" aria-label="Permalink to “5. 使用命令提示符(CMD) 运行 Docker###”">​</a></h3><p>现在，如果你想开始用命令提示符使用 Docker，你可以打开命令提示符(CMD.exe)。由于 Boot2Docker 要求 ssh.exe 在 PATH 中，我们需要在命令提示符中输入以下命令使得 %PATH% 环境变量中包括 Git 安装目录下的 bin 文件夹。</p><pre><code>set PATH=%PATH%;&quot;c:\\Program Files (x86)\\Git\\bin&quot;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-in-cmd.png" alt=""></p><p>运行上面的命令之后，我们可以在命令提示符中运行 <strong>boot2docker start</strong> 启动 Boot2Docker 虚拟机。</p><pre><code>boot2docker start
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-cmd-variables.png" alt=""></p><p><strong>注意</strong>: 如果你看到 machine does no exist 的错误信息，就运行 <strong>boot2docker init</strong> 命令。</p><p>然后复制上图中控制台标出命令到 cmd.exe 中为控制台窗口设置环境变量，然后我们就可以像平常一样运行 docker 容器了。</p><h3 id="_6-使用-powershell-运行-docker" tabindex="-1">6. 使用 PowerShell 运行 Docker <a class="header-anchor" href="#_6-使用-powershell-运行-docker" aria-label="Permalink to “6. 使用 PowerShell 运行 Docker”">​</a></h3><p>为了能在 PowerShell 中运行 Docker，我们需要启动一个 PowerShell 窗口并添加 ssh.exe 到 PATH 变量。</p><pre><code>$Env:Path = &quot;\${Env:Path};c:\\Program Files (x86)\\Git\\bin&quot;
</code></pre><p>运行完上面的命令，我们还需要运行</p><pre><code>boot2docker start
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-in-powershell.png" alt=""></p><p>这会打印用于设置环境变量连接到虚拟机内部运行的 Docker 的 PowerShell 命令。我们只需要在 PowerShell 中运行这些命令就可以和平常一样运行 docker 容器。</p><h3 id="_7-用-putty-登录" tabindex="-1">7. 用 PUTTY 登录 <a class="header-anchor" href="#_7-用-putty-登录" aria-label="Permalink to “7.  用 PUTTY 登录”">​</a></h3><p>Boot2Docker 会在%USERPROFILE%.ssh 目录生成和使用用于登录的公共和私有密钥，我们也需要使用这个文件夹中的私有密钥。私有密钥需要转换为 PuTTY 的格式。我们可以通过 puttygen.exe 实现。</p><p>我们需要打开 puttygen.exe 并从 %USERPROFILE%.ssh\\id_boot2docker 中导入(&quot;File&quot;-&gt;&quot;Load&quot; 菜单)私钥，然后点击 &quot;Save Private Key&quot;。然后用保存的文件通过 PuTTY 用 docker@127.0.0.1:2022 登录。</p><h3 id="_8-boot2docker-选项" tabindex="-1">8. Boot2Docker 选项 <a class="header-anchor" href="#_8-boot2docker-选项" aria-label="Permalink to “8. Boot2Docker 选项”">​</a></h3><p>Boot2Docker 管理工具提供了一些命令，如下所示。</p><pre><code>$ boot2docker

Usage: boot2docker.exe [&lt;options&gt;] {help|init|up|ssh|save|down|poweroff|reset|restart|config|status|info|ip|shellinit|delete|download|upgrade|version} [&lt;args&gt;]
</code></pre><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>通过 Docker Windows 客户端使用 Docker 很有趣。Boot2Docker 管理工具是一个能使任何 Docker 容器能像在 Linux 主机上平滑运行的很棒的应用程序。如果你更仔细的话，你会发现 boot2docker 默认用户的用户名是 docker，密码是 tcuser。最新版本的 boot2docker 设置了一个 host-only 的网络适配器提供访问容器的端口。一般来说是 192.168.59.103，但可以通过 VirtualBox 的 DHCP 实现改变。</p><p>如果你有任何问题、建议、反馈，请在下面的评论框中写下来然后我们可以改进或者更新我们的内容。非常感谢！Enjoy:-)</p><hr>`,42)),r("p",null,[o[11]||(o[11]=e("via: ",-1)),n(t,{href:"http://linoxide.com/linux-how-to/run-docker-client-inside-windows-os/"},{default:i(()=>[...o[10]||(o[10]=[e("http://linoxide.com/linux-how-to/run-docker-client-inside-windows-os/",-1)])]),_:1})]),r("p",null,[o[15]||(o[15]=e("作者：",-1)),n(t,{href:"http://linoxide.com/author/arunp/"},{default:i(()=>[...o[12]||(o[12]=[e("Arun Pyasi",-1)])]),_:1}),o[16]||(o[16]=e(" 译者：",-1)),n(t,{href:"https://github.com/ictlyh"},{default:i(()=>[...o[13]||(o[13]=[e("ictlyh",-1)])]),_:1}),o[17]||(o[17]=e(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:i(()=>[...o[14]||(o[14]=[e("wxy",-1)])]),_:1})]),r("p",null,[o[20]||(o[20]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...o[18]||(o[18]=[e("LCTT",-1)])]),_:1}),o[21]||(o[21]=e(" 原创翻译，",-1)),n(t,{href:"https://linux.cn/"},{default:i(()=>[...o[19]||(o[19]=[e("Linux中国",-1)])]),_:1}),o[22]||(o[22]=e(" 荣誉推出",-1))])])}const f=l(k,[["render",c]]);export{x as __pageData,f as default};
